INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('Bloccare un articolo', 'joomlaguide-locking-an-article-it', '<p>Quando qualcuno modifica un articolo, Joomla lo <em>blocca</em>: nessun altro può cambiarlo nello stesso momento. Salvando o chiudendo l\'articolo lo <em>sblocca</em> di nuovo.</p><p>Se chi lo modifica se ne va senza salvare né chiudere, l\'articolo resta bloccato. In questo tour vedi come succede e come un amministratore lo sblocca.</p><p>Questo tour segue il tutorial <a href="https://guide.joomla.org/it/tutorial-it-it/gestione-contenuti/7-pubblicazione-e-accesso/7-5-bloccare-un-articolo" target="_blank" rel="noopener">7.5 Bloccare un articolo</a> della Guida utente di Joomla.</p>', 1, '["com_cpanel","com_content"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 7.5 Locking an Article', 1, 1);
INSERT INTO `#__guidedtour_steps` (`tour_id`, `title`, `description`, `ordering`, `position`, `target`, `type`, `interactive_type`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `params`) VALUES
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-it'), 'Contenuto', '<p>Nel menu a sinistra, clicca su <strong>Contenuto</strong>.</p><p>Si apre e mostra cosa puoi fare lì.</p>', 1, 'right', 'body.com_cpanel #sidebarmenu li.item-level-1:has(a[href="index.php?option=com_content&view=articles"]) > a.has-arrow', 2, 4, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-it'), 'Contenuto › Articoli', '<p>Clicca su <strong>Articoli</strong>, in <strong>Contenuto</strong>.</p>', 2, 'right', 'body.com_cpanel #sidebarmenu a[href="index.php?option=com_content&view=articles"]', 2, 1, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-it'), 'Aprire l\'articolo', '<p>Clicca su <strong>Il Consiglio comunale approva il nuovo bilancio dei trasporti</strong> per modificarlo.</p>', 3, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Il Consiglio comunale approva il nuovo bilancio dei trasporti"]) a[href*="task=article.edit"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-it'), 'Uscire senza chiudere', '<p>Ora stai modificando l\'articolo. Non cliccare su <strong>Salva</strong> né su <strong>Chiudi</strong>: premi il pulsante <em>Indietro</em> del tuo browser. È quello che fa chi se ne va senza chiudere.</p><p>Tornato nell\'elenco, l\'articolo ha un lucchetto: è bloccato. Passa il mouse sul lucchetto per vedere chi l\'ha bloccato, e quando. (Nessun lucchetto? Ricarica la pagina.)</p>', 4, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Il Consiglio comunale approva il nuovo bilancio dei trasporti"]) th', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-it'), 'Chi può modificarlo?', '<p>L\'articolo l\'hai bloccato tu, quindi puoi ancora aprirlo. Gli altri utenti, anche gli amministratori, ricevono un messaggio di errore quando ci provano.</p><p>Quando clicchi su <strong>Chiudi</strong> o su <strong>Salva & Chiudi</strong> nell\'articolo, viene di nuovo sbloccato.</p>', 5, 'bottom', '#articleList tr:has(a[href*="task=article.edit"][title$=" Il Consiglio comunale approva il nuovo bilancio dei trasporti"])', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-it'), 'Sbloccare l\'articolo', '<p>Qui chi lo modificava non è tornato. Come amministratore puoi sbloccare l\'articolo: clicca sul lucchetto.</p>', 6, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Il Consiglio comunale approva il nuovo bilancio dei trasporti"]) [data-item-task="articles.checkin"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-it'), 'Ben fatto!', '<p>L\'articolo è sbloccato, e chiunque abbia il permesso può modificarlo di nuovo.</p><p>Per sbloccare molti articoli insieme, spunta le loro caselle e scegli <strong>Azioni</strong> › <strong>Sblocco</strong>.</p><p>Fai attenzione: se chi lo modifica sta ancora lavorando all\'articolo, le sue modifiche possono andare perse.</p>', 7, 'bottom', '#system-message-container', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL);
